// Generated by philote from page /authors. Do not edit.
import type { Metadata } from "next";
import { connection } from "next/server";
import { Suspense } from "react";

import { authors } from "@/lib/api";
import { must } from "@/lib/backend";
import { readAuthorCard } from "@/lib/reads";

import AuthorCard from "@/components/common/author-card";

export const metadata: Metadata = { title: "Authors" };

export default function Page() {
    return (
        <main className="flex-1 p-8">
            <div className="mx-auto max-w-4xl space-y-6">
                <h1 className="font-heading text-4xl">{"Authors"}</h1>
                <Suspense fallback={<p className="text-muted-foreground">Loading…</p>}>
                    <Records />
                </Suspense>
            </div>
        </main>
    );
}

async function Records() {
    await connection();
    const records = await must(authors.list());
    if (records.length === 0) {
        return <p className="text-muted-foreground">{"No authors yet."}</p>;
    }
    const items = await Promise.all(records.map(readAuthorCard));
    return (
        <div className="grid gap-4 md:grid-cols-2">
            {items.map((item) => (
                <AuthorCard key={item.author.id} {...item} />
            ))}
        </div>
    );
}
